import json
from pathlib import Path


sources = json.loads(Path('source.json').read_text())
drafts = {}


def article(number, paragraphs, reason, review_notes, **extra):
    drafts[number] = dict(
        proposed_xml=''.join('<p>' + p + '</p>' for p in paragraphs),
        reason=reason,
        review_notes=review_notes,
        **extra,
    )


article('L111-1', [
    'La sécurité sociale repose sur la solidarité nationale.',
    'Elle couvre les charges de maladie, de maternité, de paternité, de famille et d’autonomie de toute personne qui travaille en France ou qui y réside de façon stable et régulière.',
    'Elle garantit les travailleurs contre les risques de toute nature qui peuvent réduire ou supprimer leurs revenus. Cette garantie est assurée par leur affiliation à un ou plusieurs régimes obligatoires.',
    'Dans le cadre du présent code, la sécurité sociale prend en charge les frais de santé et le soutien à l’autonomie. Elle sert les prestations d’assurance sociale, notamment les allocations vieillesse, les prestations d’accidents du travail et de maladies professionnelles ainsi que les prestations familiales. Ces dispositions s’appliquent sous réserve des stipulations des conventions internationales et des dispositions des règlements européens.',
],
    'Droit constant : réécriture des quatre alinéas en conservant les bénéficiaires, tous les risques couverts, l’affiliation obligatoire et la réserve internationale. Seconde passe : aucune suppression supplémentaire n’est justifiée. Cet article fonde les garanties de santé, de revenus, de famille et d’autonomie ; il ne prescrit ni dossier supplémentaire ni prélèvement déterminé. Retirer une branche ou l’affiliation obligatoire supprimerait une protection essentielle et dépasserait les réformes décidées.',
    'Les quatre alinéas sont conservés : la couverture visée par L. 111-2 reste au deuxième alinéa. La réserve internationale reste dans le quatrième et concerne l’ensemble des prises en charge et prestations qui y sont énoncées. L. 111-2-2 précise le rattachement professionnel, y compris à l’étranger ; la condition de résidence stable et régulière n’est pas ajoutée aux travailleurs du seul fait de cette réécriture. Les baisses de CSG et de C3S relèvent de leurs articles d’assiette, de taux et de transition ; cet article ne les réalise pas.'
)

article('L111-2', [
    'Le présent code s’applique en France métropolitaine et, sous les réserves qu’il prévoit, en Guadeloupe, en Guyane, en Martinique, à La Réunion, à Saint-Barthélemy et à Saint-Martin. À Saint-Pierre-et-Miquelon, les dispositions suivantes s’appliquent également, dans les conditions prévues au titre V bis du livre VII :<br/>Les titres I<sup>er</sup>, II et V du livre I<sup>er</sup> ;<br/>La sous-section 1 de la section 1 du chapitre 1<sup>er</sup> et le chapitre 8 bis du titre VI du livre I<sup>er</sup> ;<br/>Les titres I<sup>er</sup> à IV du livre VIII ;<br/>Pour la couverture des charges mentionnées au deuxième alinéa de l’article L. 111-1, le chapitre préliminaire du titre VI du livre I<sup>er</sup>, le chapitre 3 bis du titre II du livre II et le livre V.',
    'Les professions agricoles et forestières restent soumises au régime résultant de leur statut actuel.',
],
    'Droit constant : le champ territorial est présenté par territoires puis par ensembles de dispositions applicables à Saint-Pierre-et-Miquelon. La phrase selon laquelle des lois pourront étendre le système est retirée comme rappel déclaratif de la compétence législative ; cette suppression rédactionnelle ne retire aucune obligation et n’est pas présentée comme une baisse de charge. Seconde passe : les limites territoriales et la réserve agricole sont nécessaires pour éviter une extension involontaire des régimes et de la capitalisation ; aucune coupe normative supplémentaire n’est justifiée.',
    'Les deux alinéas de la source sont conservés ; la liste interne au premier utilise des sauts de ligne sans créer de nouveaux 1° à 4°. Tous les renvois territoriaux sont maintenus, notamment le titre V bis du livre VII et le deuxième alinéa de L. 111-1. La note source fixe au 23 juillet 2026 l’entrée en vigueur de la rédaction issue de l’ordonnance n° 2026-648 du 22 juillet 2026 ; elle ne date pas la réforme proposée. La version assignée est signalée ABROGE_DIFF et cesse d’être applicable le 1er janvier 2028 : coordonner la rédaction appelée à lui succéder et les dispositions ultramarines correspondantes, sans prolonger tacitement cette version. La réserve agricole interdit d’étendre automatiquement la première phase de L. 241-3 aux salariés agricoles.'
)

article('L111-2-1', [
    'I. — La prise en charge des frais de santé par la sécurité sociale est universelle, obligatoire et solidaire.',
    'Chacun est protégé contre le risque et les conséquences de la maladie, quels que soient son âge et son état de santé. Chacun contribue au financement de cette protection en fonction de ses ressources.',
    'L’État définit les objectifs de la politique de santé publique et garantit aux assurés un accès effectif aux soins sur l’ensemble du territoire.',
    'Les organismes gestionnaires des régimes d’assurance maladie participent à la mise en œuvre de la politique nationale de santé définie par l’État, dans les conditions prévues à l’article L. 1411-2 du code de la santé publique. Ils agissent en partenariat avec les organisations représentatives des professionnels de santé et les associations agréées en application de l’article L. 1114-1 du même code.',
    'Chacun contribue, pour sa part, au bon usage des ressources que la Nation consacre à l’assurance maladie.',
    'II. — Le système de retraite associe un socle obligatoire et solidaire par répartition, une capitalisation collective individualisée obligatoire constituée progressivement par transfert de cotisations vieillesse existantes, et une épargne supplémentaire libre. La première phase de transfert concerne les salariés relevant du régime général employés par une personne de droit privé, dans le champ et les conditions prévus à l’article L. 241-3. Les autres statuts et régimes ne sont concernés qu’après l’adoption des dispositions organisant leur raccordement et leur financement. La répartition assure aux retraités des pensions en rapport avec les revenus tirés de leur activité. Le transfert préserve les pensions liquidées et les droits déjà constitués dans les régimes d’origine ; il n’ouvre pas de droits futurs par répartition pour la fraction de cotisations affectée au compte individuel investi collectivement.',
    'Les assurés bénéficient d’un traitement équitable quant à la durée de leur retraite et au montant de leur pension, quels que soient leur sexe, leurs activités et parcours professionnels passés, leur espérance de vie en bonne santé, les régimes dont ils relèvent et leur génération.',
    'La solidarité s’exerce entre les générations et au sein de chaque génération. Elle comprend notamment l’égalité entre les femmes et les hommes, la prise en compte des périodes de privation involontaire d’emploi, totale ou partielle, et la garantie d’un niveau de vie satisfaisant pour tous les retraités. La Nation se fixe pour objectifs de réduire de moitié, à l’horizon 2037, l’écart entre les pensions des femmes et celles des hommes constaté en 2023, et de le supprimer à l’horizon 2050.',
    'La pérennité financière du socle par répartition repose sur des contributions réparties équitablement entre les générations et, au sein de chaque génération, entre les niveaux de revenus et entre les revenus du travail et du capital. Elle suppose de rechercher le plein emploi. Le premier transfert de cotisations et chaque passage à un palier supérieur sont subordonnés à un financement pérenne voté couvrant la perte de recettes de la répartition, les abondements de solidarité et les frais de transition, dans les conditions de l’article L. 241-3. Aucun transfert ne peut commencer avant l’entrée en vigueur des règles de calcul protégeant les droits antérieurs et réduisant exactement les droits futurs correspondant à la fraction transférée, ainsi que des règles de gouvernance, de gestion, de contrôle et de liquidation des comptes prévues au même article. La loi détermine les étapes, les taux, les garanties de gestion, les abondements de solidarité et les conditions de sortie. Aucun rendement futur n’est réputé financer une dépense présente. Ni le capital soumis aux fluctuations de marché ni son rendement ne bénéficient d’une garantie générale implicite de l’État.',
    'III. — La sécurité sociale assure une prise en charge universelle et solidaire du soutien à l’autonomie.',
    'Chacun bénéficie d’une protection contre le risque de perte d’autonomie et du soutien à l’autonomie nécessaire, quels que soient son âge et son état de santé.',
],
    'Droit constant aux I et III : les garanties de santé et d’autonomie, la contribution selon les ressources et le partenariat sanitaire restent complets. Réforme de fond au II, conservée de la première proposition : combinaison de répartition, capitalisation collective individualisée et épargne libre, avec réduction des seuls droits futurs correspondant aux cotisations transférées et protection des droits antérieurs. La seconde passe supprime la portée trop générale de la première proposition en bornant expressément la première phase aux salariés du régime général employés par une personne de droit privé. Aucun nouveau prélèvement ni suppression supplémentaire des protections sanitaires ou de solidarité n’est justifié : le financement des pensions présentes, l’équité et la prévention d’une double promesse de droits restent indispensables.',
    'Les I, II et III restent à leur place et les onze alinéas de la source sont conservés ; les ajouts du II sont intégrés à ses premier et quatrième alinéas. Les renvois L. 1114-1 et L. 1411-2 du code de la santé publique ainsi que les objectifs 2037, 2023 et 2050 sont maintenus. Coordination avec les II à VII de L. 241-3 : paliers de 0,5 %, 1 %, 2 %, 3 %, puis 4 %, par périodes de deux ans, plafonnement des frais à 0,35 %, absence de frais d’entrée et de transfert, séparation des actifs et financement préalable ; ces paramètres opérationnels ne sont pas dupliqués ici. La protection des pensions lors du transfert ne supprime pas la transition distincte de L. 161-23-1 : trois ans au maximum, seule fraction des pensions brutes cumulées au-delà de 2 000 euros mensuels, seuil revalorisé et nominal préservé. Les dispositions de calcul de L. 351-1 et de ses textes réglementaires, la gouvernance et les sorties des comptes doivent être coordonnées avant le premier transfert ; leur adoption n’est pas présumée. Hors du lot, identifier le raccordement des accords AGIRC-ARRCO, du code rural et de la pêche maritime et du code des pensions civiles et militaires de retraite pour toute extension. Le traitement civil du capital au décès nécessite des dispositions nouvelles identifiées, sans numéro inventé, et sa fiscalité doit respecter l’abolition des prélèvements sur les capitaux dénoués par décès ; les donations entre vifs restent distinctes. Les conditions européennes de coordination et de gestion des retraites professionnelles restent à articuler selon la qualification du dispositif. La note source du 1er septembre 2023 concerne les pensions sous la rédaction antérieure ; elle ne fixe aucune date pour le nouveau transfert. Le bon usage des ressources n’est pas transformé en une déclaration supplémentaire des assurés.',
    change_type='normative_reduction',
    reform_policy_id='editorial_direction_2026_10_19',
    removed_provisions=[
        'Acquisition des droits futurs par répartition correspondant à la seule fraction des cotisations vieillesse effectivement transférée vers la capitalisation, après financement voté et entrée en vigueur des règles coordonnées de calcul ; les pensions liquidées et les droits déjà constitués restent protégés.'
    ],
)

article('L111-2-2', [
    'Sous réserve des traités et accords internationaux régulièrement ratifiés ou approuvés et des règlements européens, les personnes suivantes sont affiliées à un régime obligatoire de sécurité sociale dans le cadre du présent code, quel que soit leur lieu de résidence :',
    '1° Les personnes qui exercent sur le territoire français :',
    'a) Une activité pour le compte d’un ou de plusieurs employeurs, qu’ils disposent ou non d’un établissement en France ;',
    'b) Une activité professionnelle non salariée ;',
    '2° Les personnes qui exercent une activité professionnelle à l’étranger et sont soumises à la législation française de sécurité sociale en application des règlements européens ou des conventions internationales.',
],
    'Droit constant : la phrase d’affiliation est réécrite et les deux catégories ainsi que les a) et b) sont maintenus. Seconde passe : aucune coupe supplémentaire n’est justifiée. Le rattachement par l’activité assure l’accès aux droits et empêche de contourner l’affiliation par une résidence ou un employeur à l’étranger ; la réserve internationale évite un assujettissement incompatible avec les règles de coordination. L’article ne crée aucune déclaration ou cotisation autonome à supprimer.',
    'Les cinq alinéas et les cibles 1°, a), b) et 2° sont préservés. La réserve des traités, accords régulièrement ratifiés ou approuvés et règlements européens reste dans l’alinéa introductif. Le lieu de résidence et l’existence d’un établissement de l’employeur en France ne deviennent pas des conditions d’affiliation. La capitalisation de L. 241-3 ne s’étend pas à toute personne mentionnée ici : son champ propre et les règles internationales restent distincts.'
)

article('L111-2-3', [
    'Un décret en Conseil d’État précise les conditions dans lesquelles sont appréciées la stabilité de la résidence et la régularité du séjour mentionnées à l’article L. 111-1, sans préjudice des règles particulières applicables au service des prestations ou des allocations.',
    'Pour cette appréciation, l’organisme utilise les pièces et informations exactes et à jour pour la date ou la période examinée qu’il détient ou auxquelles il a légalement accès. Il ne peut demander à l’intéressé de les produire à nouveau lorsqu’elles établissent le respect des conditions pour cette date ou cette période. Une pièce complémentaire ne peut être exigée que si les éléments ainsi disponibles sont insuffisants ou présentent une incohérence nécessitant une vérification au regard de cette date ou de cette période ; la demande est limitée aux éléments nécessaires à cette vérification. Lorsque la régularité du séjour doit être appréciée au jour de la demande de prestation, la seule expiration du titre après ce jour ne justifie pas une nouvelle production. Le présent article n’ouvre aucun accès à des données qui ne serait pas autorisé par les dispositions applicables et ne déroge ni aux secrets protégés ni aux règles de protection des données personnelles.',
    'Aucun renouvellement périodique des mêmes justificatifs ne peut être exigé si les éléments légalement disponibles établissent toujours le respect des conditions pour la période examinée. Cette règle ne dispense pas les intéressés des obligations légales de signaler les changements de leur situation. Elle ne supprime ni les conditions de résidence et de séjour, ni les vérifications et contrôles nécessaires, ni les règles de récupération des indus et de lutte contre la fraude. Une suspension ou une fermeture des droits ne peut être fondée sur la seule absence de nouvelle production d’une pièce que l’organisme ne pouvait exiger en application du présent article.',
    'Les deuxième et troisième alinéas s’appliquent dès l’entrée en vigueur de la présente loi aux demandes et aux contrôles en cours. Les demandes portant exclusivement sur une nouvelle production interdite par ces alinéas deviennent sans objet, sans que leur absence de réponse puisse justifier une suspension ou une fermeture des droits. Les contrôles et les créances concernant les périodes antérieures sont préservés ; le présent article ne rouvre aucun délai de recours expiré et n’emporte aucune restitution générale des sommes antérieurement recouvrées.',
],
    'Droit constant au premier alinéa : maintien du décret en Conseil d’État, des deux conditions et des règles particulières de service. Réduction de fond nouvelle : interdiction opposable de redemander les preuves exactes, actuelles et légalement disponibles, ainsi que de renouveler automatiquement les mêmes justificatifs lorsqu’ils établissent encore les conditions pour la période contrôlée. La première proposition se limitait à reformuler l’habilitation ; la seconde retire les exigences documentaires redondantes que son application pourrait permettre et leur effet bloquant sur les droits. Elle ne prétend pas que la source impose elle-même une périodicité ou un formulaire déterminés.',
    'Le premier alinéa conserve sa fonction et sa place ; les règles de preuve sont ajoutées à sa suite. Lecture de R. 111-2 : preuve de la résidence par tout moyen et durées particulières de plus de neuf ou de six mois maintenues, sans les uniformiser ici. Lecture de R. 111-3 : titres de séjour et appréciation au jour de la demande restent distincts de la réutilisation des preuves. Coordonner R. 114-10 et R. 114-10-1 : ni le délai d’un mois pour les compléments réellement nécessaires ni le contradictoire, les délais de quarante-cinq jours et les recours ne sont supprimés ; une demande redondante ne doit plus déclencher leurs conséquences défavorables. Les contrôles de L. 114-10 et les obligations antifraude restent applicables. Conserver le même champ aux renvois de L. 115-6, L. 160-1, L. 161-8, L. 161-16-1 et L. 512-1. La nouvelle règle ne crée pas une interconnexion générale des fichiers ; toute extension d’échange de données exigerait son fondement propre et les garanties applicables. Aucun nouvel examen d’une période déjà définitivement close ni aucune suppression rétroactive de dette n’est décidé. Aucune date calendaire d’entrée en vigueur n’est inventée.',
    change_type='normative_reduction',
    reform_policy_id='editorial_direction_2026_10_19',
    removed_provisions=[
        'Toute exigence de nouvelle production par l’intéressé de justificatifs de résidence ou de séjour exacts et à jour, déjà détenus par l’organisme ou légalement accessibles, lorsqu’ils suffisent pour la période examinée.',
        'Tout renouvellement périodique des mêmes justificatifs sans insuffisance des éléments disponibles pour la période examinée, ainsi que la suspension ou la fermeture des droits fondée sur la seule absence de réponse à cette demande redondante.'
    ],
)

article('LO111-3', [
    'Les trois catégories de lois suivantes ont le caractère de loi de financement de la sécurité sociale :',
    '1° La loi de financement de la sécurité sociale de l’année ;',
    '2° La loi de financement rectificative de la sécurité sociale ;',
    '3° La loi d’approbation des comptes de la sécurité sociale.',
],
    'Droit constant : réécriture de la qualification des trois catégories de lois, avec leurs numéros conservés. Seconde passe : aucune suppression supplémentaire n’est justifiée. L’autorisation annuelle, la correction en cours d’exercice et l’approbation des comptes clos ont des objets différents ; leur fusion ferait disparaître une étape du contrôle financier sans supprimer un doublon établi. Cette règle de qualification ne crée pas de démarche pour les particuliers ou les entreprises.',
    'Disposition organique : sa réécriture relève d’une loi organique et du contrôle constitutionnel prévu pour celle-ci. Les quatre alinéas substantiels et les 1° à 3° restent en place. La note source de l’article 9 de la loi organique n° 2022-354 du 14 mars 2022 fixe l’entrée en vigueur historique au 1er septembre 2022 et maintient pour la LFSS 2023 les cinq premiers alinéas, le A du I et le VIII de l’ancienne rédaction ; ces règles historiques ne sont ni effacées ni redatées par la proposition. La qualification de LFSS ne confère pas à une loi ordinaire le pouvoir de modifier ces dispositions organiques.'
)

article('LO111-3-1', [
    'La loi de financement de la sécurité sociale de l’année comporte un article liminaire et trois parties :',
    '1° La première partie comprend les dispositions relatives à l’année en cours ;',
    '2° La deuxième partie comprend les dispositions relatives aux recettes et à l’équilibre général pour l’année à venir ;',
    '3° La troisième partie comprend les dispositions relatives aux dépenses pour l’année à venir.',
],
    'Droit constant : rédaction directe de l’architecture de la loi annuelle, sans modifier ses trois parties ni les exercices concernés. Seconde passe : aucune coupe supplémentaire n’est justifiée. La séparation des exercices et des recettes et dépenses structure les votes et les renvois organiques ; l’article liminaire porte sur un périmètre plus large que les seuls régimes de base et ne constitue pas un doublon démontré. Le traitement simplifié des données inchangées est porté à LO 111-3-3, où se situe l’obligation correspondante.',
    'Les quatre alinéas, les 1° à 3° et leur ordre sont maintenus pour les renvois des articles organiques suivants. La note source du 1er septembre 2022 reste une disposition d’entrée en vigueur historique. Loi organique requise. L’annualité de la loi de financement ne constitue pas un fait générateur annuel d’IS et n’autorise ni impôt ni acompte sur des bénéfices conservés ; l’IS à la distribution et ses effets sur les recettes affectées se coordonnent dans les articles fiscaux concernés.'
)

article('LO111-3-2', [
    'L’article liminaire de la loi de financement de la sécurité sociale de l’année présente les prévisions de dépenses, de recettes et de solde des administrations de sécurité sociale pour l’exercice en cours et pour l’année à venir.',
],
    'Droit constant : la règle complète est réécrite en un alinéa, avec maintien des trois agrégats et des deux exercices. Seconde passe : aucune suppression supplémentaire n’est justifiée. Les administrations de sécurité sociale ont un périmètre différent de celui des régimes obligatoires de base visés dans les tableaux des parties suivantes ; leur solde agrégé est nécessaire à l’information du Parlement et à l’articulation des finances publiques. Aucune déclaration supplémentaire des assurés ou employeurs n’est prescrite ici.',
    'Le seul alinéa de la source est conservé. Ne pas confondre les administrations de sécurité sociale avec les seuls régimes obligatoires de base ou avec les seuls organismes qui les financent. Les prévisions de dépenses, recettes et solde couvrent à la fois l’exercice en cours et l’année à venir. Note historique d’entrée en vigueur au 1er septembre 2022 maintenue dans son champ ; réécriture organique, sans nouvelle périodicité fiscale.'
)

article('LO111-3-3', [
    'Dans sa première partie, relative à l’année en cours, la loi de financement de la sécurité sociale de l’année :',
    '1° Rectifie, lorsqu’ils sont modifiés, les prévisions de recettes et les tableaux d’équilibre des régimes obligatoires de base, par branche, ainsi que ceux des organismes concourant au financement de ces régimes ;',
    '2° Rectifie, lorsqu’ils sont modifiés, les objectifs de dépenses de ces régimes, par branche, l’objectif national de dépenses d’assurance maladie de l’ensemble des régimes obligatoires de base ainsi que leurs sous-objectifs approuvés dans la précédente loi de financement de la sécurité sociale ;',
    '3° Rectifie, lorsqu’ils sont modifiés, l’objectif assigné aux organismes chargés de l’amortissement de la dette des régimes obligatoires de base et des organismes concourant à leur financement, ainsi que les prévisions de recettes affectées à la mise en réserve à leur profit.',
    'Les prévisions, tableaux, objectifs et sous-objectifs mentionnés aux 1° à 3° dont les montants, le périmètre et l’exercice de référence demeurent identiques sont expressément maintenus par un renvoi précis aux dispositions qui les ont approuvés ou rectifiés en dernier lieu. Leur reproduction n’est pas exigée. Le renvoi identifie chaque donnée maintenue et ne peut porter sur un élément modifié, lequel reste soumis à la rectification prévue au 1°, au 2° ou au 3°. Les documents auxquels il renvoie sont mis à la disposition du Parlement avec le projet de loi. Cette faculté ne dispense ni d’examiner l’actualité des prévisions ni de présenter sincèrement les modifications intervenues.',
    'Le cinquième alinéa s’applique aux projets de loi de financement déposés après l’entrée en vigueur de la présente loi organique. Il ne modifie ni les dispositions financières déjà adoptées ni les règles applicables aux projets déposés antérieurement.',
],
    'Droit constant pour les périmètres financiers et les trois catégories numérotées de rectifications. Réduction de fond nouvelle : les données demeurées strictement identiques peuvent être maintenues par un renvoi exprès au dernier vote, sans reproduction ni rectification artificielle. La première proposition imposait encore les trois rectifications sans distinguer une modification réelle d’un maintien. Le nouveau texte retire cette répétition matérielle tout en maintenant un vote de maintien identifiable, l’accès aux documents, l’actualisation sincère des prévisions et la rectification de chaque changement. Il ne supprime aucun tableau dont les données ont changé.',
    'Les quatre alinéas initiaux et les 1° à 3° restent à leur place ; la règle commune et sa transition sont ajoutées après eux. Le renvoi n’est admis qu’à montants, périmètre et exercice identiques : il ne permet pas de reprendre les chiffres d’une autre année ni d’ignorer une prévision devenue inexacte. Chaque élément doit être identifié et le document accessible au Parlement, sans renvoi global opaque. Les sous-objectifs du 2°, la dette des organismes concourant au financement et les prévisions de mise en réserve du 3° sont conservés. L’article liminaire de LO 111-3-2 et les documents de justification de LO 111-4 et LO 111-4-1 restent exigés dans leur champ ; aucune baisse automatique des obligations comptables des organismes n’est déduite de la dispense de reproduction législative. Loi organique et contrôle constitutionnel requis, notamment sur la clarté des votes et l’information parlementaire. La note du 1er septembre 2022 demeure historique ; la nouvelle faculté ne vaut que pour les projets déposés après l’entrée en vigueur de la réforme organique.',
    change_type='normative_reduction',
    reform_policy_id='editorial_direction_2026_10_19',
    removed_provisions=[
        'Obligation de reproduire dans la première partie de la loi annuelle les prévisions, tableaux d’équilibre, objectifs et sous-objectifs inchangés à montants, périmètre et exercice identiques, lorsque leur maintien exprès est voté par un renvoi précis au dernier texte les ayant approuvés ou rectifiés.',
        'Obligation de procéder à une rectification purement formelle des éléments financiers strictement inchangés visés aux 1° à 3° ; leur examen actualisé et leur maintien exprès restent obligatoires, et toute donnée modifiée doit toujours être rectifiée.'
    ],
)

article('LO111-3-4', [
    'Dans sa deuxième partie, relative aux recettes et à l’équilibre général pour l’année à venir, la loi de financement de la sécurité sociale de l’année :',
    '1° Approuve le rapport prévu à l’article LO 111-4 ;',
    '2° Détermine de manière sincère les conditions générales de l’équilibre financier de la sécurité sociale pour l’année à venir. Elle tient notamment compte des conditions économiques générales et de leur évolution prévisible. Cet équilibre est défini au regard des données économiques, sociales et financières décrites dans le rapport prévu à l’article 50 de la loi organique n° 2001-692 du 1er août 2001 relative aux lois de finances. À cette fin, la loi de financement de l’année :',
    'a) Prévoit les recettes de l’ensemble des régimes obligatoires de base, par branche, ainsi que celles des organismes concourant au financement de ces régimes ;',
    'b) Détermine, pour l’année à venir, l’objectif d’amortissement des organismes chargés de l’amortissement de la dette des régimes obligatoires de base et des organismes concourant à leur financement. Elle prévoit, par catégorie, les recettes affectées aux organismes chargés de la mise en réserve de recettes à leur profit ;',
    'c) Approuve le montant de la compensation mentionnée à l’annexe prévue au 2° de l’article LO 111-4-1 du présent code ;',
    'd) Présente l’équilibre financier de la sécurité sociale dans des tableaux d’équilibre établis pour l’ensemble des régimes obligatoires de base, par branche, ainsi que pour les organismes concourant au financement de ces régimes ;',
    'e) Fixe la liste des régimes obligatoires de base et des organismes concourant à leur financement habilités à recourir à des ressources non permanentes. Elle fixe les limites dans lesquelles ces ressources peuvent couvrir leurs besoins de trésorerie.',
],
    'Droit constant : phrases plus directes pour les deux attributions principales et les cinq opérations financières, avec maintien de toutes les réserves et de tous les renvois. Seconde passe : aucune coupe supplémentaire n’est justifiée. L’approbation du rapport pluriannuel est distincte du vote de l’équilibre annuel ; les tableaux par branche, la compensation, l’amortissement, les réserves et les plafonds de trésorerie rendent contrôlables les pertes de recettes et l’endettement. Leur suppression masquerait le financement des réformes plutôt qu’elle ne retirerait une formalité inutile aux cotisants.',
    'Les huit alinéas, les 1° et 2° ainsi que les a) à e) sont conservés ; la formule « À cette fin » reste dans le 2°. Le e) demeure la cible des renvois de LO 111-9-2 et L. 225-1-4. Incohérence préexistante signalée, sans correction silencieuse : le c) vise l’annexe du 2° de LO 111-4-1, alors que la version de cet article consultée dans le corpus place les réductions et exonérations avec les modalités et montants de compensation au 4° ; son 2° porte sur les comptes prévisionnels d’organismes et de fonds. Mettre ces deux articles en concordance dans le véhicule organique après détermination de l’annexe effectivement visée. Le renvoi source est conservé dans la proposition pour ne pas tenir cette coordination pour acquise. Les dépenses de transition retraite et les compensations des baisses de CSG et de C3S doivent être retracées sans compter deux fois une même ressource ; ni rendement espéré ni réinvestissement attendu ne prouvent un financement disponible. Les effets de l’IS à la distribution et de l’abolition des droits au décès sur les recettes éventuellement affectées doivent être évalués, sans créer par cet article un prélèvement de remplacement. Réécriture organique ; note d’entrée en vigueur du 1er septembre 2022 conservée dans son champ historique.'
)

article('LO111-3-5', [
    'Dans sa troisième partie, relative aux dépenses pour l’année à venir, la loi de financement de la sécurité sociale de l’année :',
    '1° Fixe les charges prévisionnelles des organismes concourant au financement des régimes obligatoires de base ;',
    '2° Fixe les objectifs de dépenses de l’ensemble des régimes obligatoires de base, par branche, ainsi que, le cas échéant, leurs sous-objectifs. Le Gouvernement fixe la liste et le périmètre de ces éventuels sous-objectifs après consultation des commissions parlementaires saisies au fond des projets de loi de financement de la sécurité sociale ;',
    '3° Fixe l’objectif national de dépenses d’assurance maladie de l’ensemble des régimes obligatoires de base ainsi que ses sous-objectifs. La définition des composantes des sous-objectifs relève de l’initiative du Gouvernement. Les commissions parlementaires saisies au fond des projets de loi de financement de la sécurité sociale sont consultées sur la liste des sous-objectifs et la définition de leurs composantes. L’objectif national de dépenses d’assurance maladie comporte au moins trois sous-objectifs.',
],
    'Droit constant : distinction plus lisible entre charges des organismes, objectifs par branche et objectif national de dépenses d’assurance maladie, sans changer les compétences et consultations. Seconde passe : aucune coupe supplémentaire n’est justifiée. Les charges et objectifs portent sur des périmètres différents ; les sous-objectifs permettent au Parlement de contrôler la répartition des dépenses de santé. Leur minimum de trois et les consultations ne constituent pas un doublon démontré ni une démarche imposée aux patients ou employeurs. Les retirer sans réorganisation documentée affaiblirait le contrôle financier utile aux transitions décidées.',
    'Les quatre alinéas et les 1° à 3° sont conservés. Les sous-objectifs de branche du 2° restent éventuels ; ceux de l’ONDAM du 3° restent obligatoires et au moins au nombre de trois. La compétence gouvernementale sur les composantes et les deux champs de consultation sont maintenus. LO 111-10-2 conserve ses cibles aux 2° et 3°, son délai de quinze jours francs et l’avis réputé rendu à son expiration. Les renvois sectoriels au 3°, notamment L. 162-12-22, L. 162-14-1-1, L. 162-14-4, L. 162-16-1 et L. 162-17-3, gardent leur cible. L’article n’autorise ni gel d’autres prestations ni baisse des garanties sanitaires. Réécriture organique ; la note du 1er septembre 2022 ne date pas la proposition.'
)

article('LO111-3-6', [
    'La première partie de la loi de financement de la sécurité sociale de l’année, relative à l’année en cours, peut comprendre :',
    '1° Les dispositions qui ont un effet sur les recettes des régimes obligatoires de base ou des organismes concourant à leur financement, à l’amortissement de leur dette ou à la mise en réserve de recettes à leur profit ;',
    '2° Les dispositions relatives à l’affectation de ces recettes, sous réserve du III de l’article 2 de la loi organique n° 2001-692 du 1er août 2001 relative aux lois de finances ;',
    '3° Les dispositions qui ont un effet sur les dépenses de ces régimes ou organismes ;',
    '4° Les dispositions qui ont un effet sur les dettes suivantes, à condition qu’elles modifient les conditions générales de l’équilibre financier de la sécurité sociale :',
    'a) La dette des établissements de santé relevant du service public hospitalier ;',
    'b) La dette des établissements médico-sociaux publics et privés à but non lucratif, financés en tout ou partie par les régimes obligatoires de base de sécurité sociale et soumis à un objectif de dépenses ;',
    '5° Les dispositions qui améliorent l’information et le contrôle du Parlement sur l’application des lois de financement de la sécurité sociale.',
],
    'Droit constant : rédaction directe du domaine facultatif de la première partie, avec maintien de toutes ses catégories et de la condition propre aux dettes du 4°. Seconde passe : aucune coupe supplémentaire n’est justifiée. Cet article autorise des dispositions sans imposer leur adoption, un rapport périodique ou un prélèvement. En supprimer une catégorie réduirait les possibilités de correction financière ou de contrôle parlementaire ; enlever les conditions du 4° élargirait le domaine organique au lieu de retirer une charge identifiée.',
    'Les huit alinéas, les 1° à 5° et les a) et b) du 4° sont maintenus. La modification des conditions générales de l’équilibre ne conditionne que le 4°, non les 1° à 3° ou le 5°. Le b) conserve cumulativement le caractère public ou privé à but non lucratif, le financement total ou partiel par les régimes obligatoires de base et la soumission à un objectif de dépenses. La réserve du III de l’article 2 de la loi organique relative aux lois de finances reste au 2°. Ni l’existence de cette faculté d’insertion ni la réécriture ne valent adoption d’un financement pour la transition retraite. Loi organique requise ; note historique du 1er septembre 2022 préservée.'
)


assert len(sources) == 12
assert set(drafts) == {a['number'] for a in sources}
answer = []
for source in sources:
    result = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    result.update(drafts[source['number']])
    result['status'] = 'rewrite_draft'
    answer.append(result)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
